function validate([s, k]) {
  if (typeof s !== 'string' || s.length < 1 || s.length > 800) return 's needs 1 to 800 binary digits.';
  if (!/^[01]+$/.test(s)) return 's may contain only the characters 0 and 1.';
  if (s.length > 1 && s[0] === '0') return 's must not have leading zeros.';
  if (!Number.isInteger(k) || k < 1 || k > 5) return 'k is a whole number from 1 to 5.';
  return null;
}

