function countKReducibleNumbers(s, k) {
  const MOD = 1e9 + 7;
  const len = s.length;
  const steps = new Array(len + 1).fill(0);
  for (let c = 2; c <= len; c++) {
    let ones = 0;
    for (let v = c; v > 0; v >>= 1) {
      ones += v & 1;
    }
    steps[c] = 1 + steps[ones];
  }

  const smaller = new Array(len + 1).fill(0);
  let tightOnes = 0;
  for (let i = 0; i < len; i++) {
    for (let c = i + 1; c >= 1; c--) {
      smaller[c] = (smaller[c] + smaller[c - 1]) % MOD;
    }
    if (s[i] === '1') {
      smaller[tightOnes] = (smaller[tightOnes] + 1) % MOD;
      tightOnes++;
    }
  }

  let answer = 0;
  for (let c = 1; c <= len; c++) {
    if (steps[c] < k) {
      answer = (answer + smaller[c]) % MOD;
    }
  }
  return answer;
}

