function countKReducibleNumbers(s, k) {
  // Try every x from 1 to n - 1 and apply up to k steps to it directly.
  const n = parseInt(s, 2);
  const onesIn = x => [...x.toString(2)].filter(bit => bit === '1').length;
  let count = 0;
  for (let x = 1; x < n; x++) {
    let value = x;
    for (let used = 0; used < k && value !== 1; used++) value = onesIn(value);
    if (value === 1) count++;
  }
  return count % 1000000007;
}

