function generate(rand, size) {
  const pick = n => Math.floor(rand() * n);
  const k = 1 + pick(5);
  if (size === 'large') {
    // Long numbers whose bits are balanced, mostly ones, mostly zeros, or all ones.
    const length = 700 + pick(101), density = [0.5, 0.9, 0.1, 1][pick(4)];
    let s = '1';
    for (let i = 1; i < length; i++) s += rand() < density ? '1' : '0';
    return [s, k];
  }
  // Small: at most 12 bits, shaped as all ones, a power of two, or random bits.
  const length = 1 + pick(12), shape = pick(4);
  let s = '1';
  for (let i = 1; i < length; i++) s += shape === 0 ? '1' : shape === 1 ? '0' : rand() < 0.5 ? '1' : '0';
  return [s, k];
}
